#!/usr/bin/env bash
# instruction-files.sh — will Claude Code read AGENTS.md here, and what stops it.
#
# Since 2.1.277 Claude Code reads AGENTS.md as the project instructions, but
# with the default `claude-md-or-agents-md` only when no CLAUDE.md,
# .claude/CLAUDE.md or CLAUDE.local.md sits in the directory or above it. The
# setup used to write a one-line CLAUDE.md holding `@AGENTS.md`; it writes none
# now, and this script tells the shim it wrote from a CLAUDE.md the team wrote —
# the one recognition that can destroy instructions, so it is code with
# fixtures, not prose (DE-17167).
#
# Read-only in every mode: it removes nothing and writes nothing. The setup
# (Step 5b) runs `rm` on the SHIMS paths and writes the --merge output, the same
# split as render-template.sh.
#
# Usage:
#   instruction-files.sh [--json] [--dir <path>]
#   instruction-files.sh --merge <path> [--dir <path>]
#
#   --json          emit a flat JSON object
#   --dir <path>    the tree to scan (default: the repository root, else the
#                   current directory)
#   --merge <path>  print the owning AGENTS.md with the content of the CUSTOM
#                   file <path> (relative to --dir) appended at its end, under
#                   `## Instructions moved from CLAUDE.md` — after the
#                   `*Generated by:` footer when there is one, which is the part
#                   the setup's UPDATE offer never touches. `@AGENTS.md` lines
#                   and edge blank lines are dropped; when nothing is left, the
#                   AGENTS.md comes back unchanged
#
# Keys (lists are one path per line, relative to --dir unless said otherwise):
#   SHIMS               every CLAUDE.md whose whole content is `@AGENTS.md`,
#                       trailing whitespace and carriage returns stripped
#   CUSTOM              every other CLAUDE.md or .claude/CLAUDE.md whose owning
#                       directory (the parent of .claude/ for the second form)
#                       has an AGENTS.md
#   UNIMPORTED          the CUSTOM files with no `@AGENTS.md` line: Claude Code
#                       reads them and not the AGENTS.md beside them
#   LOCAL               every CLAUDE.local.md
#   ABOVE               absolute paths of the CLAUDE.md, .claude/CLAUDE.md and
#                       CLAUDE.local.md in the directories strictly above --dir,
#                       up to /; the user's ~/.claude/CLAUDE.md does not count
#   CLAUDE_VERSION      the first N.N.N of `claude --version`, or ""
#   MIN_CLAUDE_VERSION  the floor below which AGENTS.md is not read everywhere
#   VERSION_OK          true | false, compared per component; "" when unknown
#
# .git/, node_modules/ and .claude/worktrees/ are never scanned.
#
# Exit: 0 · 1 usage error, a --dir that does not exist, no jq, or a --merge
# path that is not in CUSTOM
# ---8<--- end of the --help message

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=./common.sh
source "$SCRIPT_DIR/common.sh"

# Before v2.1.281 a session on Amazon Bedrock or with telemetry disabled still
# reads CLAUDE.md only, so 2.1.277 — where AGENTS.md support starts — is not
# enough for a project with no CLAUDE.md. README.md and docs/onboarding.md name
# the same version, and the suite keeps the three equal.
MIN_CLAUDE_VERSION="2.1.281"

MERGE_HEADING="## Instructions moved from CLAUDE.md"

AS_JSON=false
DIR=""
MERGE_PATH=""

usage() {
  awk 'NR == 1 { next } /^# ---8<---/ { exit } /^#/ { sub(/^# ?/, ""); print }' \
    "${BASH_SOURCE[0]}"
}

while [ $# -gt 0 ]; do
  case "$1" in
    --json) AS_JSON=true; shift ;;
    --dir)
      [ $# -ge 2 ] || die "--dir requires a path"
      DIR="$2"; shift 2 ;;
    --merge)
      [ $# -ge 2 ] || die "--merge requires a path"
      MERGE_PATH="$2"; shift 2 ;;
    -h|--help) usage; exit 0 ;;
    *) die "unknown argument: $1 (see --help)" ;;
  esac
done

require_jq

if [ -n "$DIR" ]; then
  [ -d "$DIR" ] || die "directory not found: $DIR"
  # The logical path, not the physical one: ABOVE is read against the path the
  # caller knows, and on macOS /tmp and /var are symlinks.
  DIR="$(cd "$DIR" && pwd)" || die "cannot enter $DIR"
else
  DIR="$(repo_root)"
fi

# ── The scan ──────────────────────────────────────────────────────────────────

# The whole content with every trailing space, tab, CR and newline removed.
trimmed_content() {
  local content
  content="$(cat "$1" 2>/dev/null)"
  printf '%s' "${content%"${content##*[![:space:]]}"}"
}

# True when one line of the file, trailing whitespace aside, is `@AGENTS.md`.
imports_agents() {
  grep -qE '^@AGENTS\.md[[:space:]]*$' "$1" 2>/dev/null
}

# The directory a CLAUDE.md belongs to, relative to --dir ("" for the root):
# its own directory, or the parent of .claude/ for .claude/CLAUDE.md.
owning_dir() {
  local rel_dir
  rel_dir="$(dirname "$1")"
  [ "$rel_dir" = "." ] && rel_dir=""
  case "$rel_dir" in
    .claude) rel_dir="" ;;
    */.claude) rel_dir="${rel_dir%/.claude}" ;;
  esac
  printf '%s' "$rel_dir"
}

# The owning AGENTS.md of a CLAUDE.md, relative to --dir.
owning_agents() {
  local owner
  owner="$(owning_dir "$1")"
  printf '%s' "${owner:+$owner/}AGENTS.md"
}

SHIMS=""
CUSTOM=""
UNIMPORTED=""
LOCAL=""

append() {
  # $1 = the list's current value, $2 = the line to add.
  if [ -z "$1" ]; then printf '%s' "$2"; else printf '%s\n%s' "$1" "$2"; fi
}

# A symlinked CLAUDE.md is read through its target, so it is scanned too: it
# is never a shim, since the setup never wrote one.
while IFS= read -r FOUND; do
  [ -n "$FOUND" ] || continue
  REL="${FOUND#"$DIR"/}"
  case "$REL" in
    CLAUDE.local.md|*/CLAUDE.local.md)
      LOCAL="$(append "$LOCAL" "$REL")"
      continue ;;
  esac

  # Only a CLAUDE.md beside its AGENTS.md was ever the shim: an `@AGENTS.md`
  # inside .claude/ points at .claude/AGENTS.md.
  case "$REL" in
    .claude/CLAUDE.md|*/.claude/CLAUDE.md) IN_DOT_CLAUDE=true ;;
    *) IN_DOT_CLAUDE=false ;;
  esac
  if [ "$IN_DOT_CLAUDE" = false ] && [ ! -L "$FOUND" ] \
     && [ "$(trimmed_content "$FOUND")" = "@AGENTS.md" ]; then
    SHIMS="$(append "$SHIMS" "$REL")"
    continue
  fi

  [ -f "$DIR/$(owning_agents "$REL")" ] || continue
  CUSTOM="$(append "$CUSTOM" "$REL")"
  imports_agents "$FOUND" || UNIMPORTED="$(append "$UNIMPORTED" "$REL")"
done <<EOF
$(find "$DIR" \( -name .git -o -name node_modules -o -path '*/.claude/worktrees' \) -prune \
    -o \( -name CLAUDE.md -o -name CLAUDE.local.md \) \( -type f -o -type l \) -print 2>/dev/null \
  | LC_ALL=C sort)
EOF

# ── --merge ───────────────────────────────────────────────────────────────────

if [ -n "$MERGE_PATH" ]; then
  MERGE_PATH="${MERGE_PATH#./}"
  printf '%s\n' "$CUSTOM" | grep -qxF "$MERGE_PATH" \
    || die "$MERGE_PATH is not a CLAUDE.md that shadows an AGENTS.md (not in CUSTOM)"

  AGENTS_FILE="$DIR/$(owning_agents "$MERGE_PATH")"

  # The moved lines: CRs dropped, every `@AGENTS.md` line dropped, then the
  # blank lines at either end.
  BODY="$(awk '
    { sub(/\r$/, ""); t = $0; sub(/[[:space:]]+$/, "", t) }
    t == "@AGENTS.md" { next }
    { lines[++n] = $0 }
    END {
      s = 1; while (s <= n && lines[s] ~ /^[[:space:]]*$/) s++
      e = n; while (e >= s && lines[e] ~ /^[[:space:]]*$/) e--
      for (i = s; i <= e; i++) print lines[i]
    }' "$DIR/$MERGE_PATH")" || die "cannot read $MERGE_PATH"

  cat "$AGENTS_FILE" || die "cannot read $AGENTS_FILE"
  [ -n "$BODY" ] || exit 0

  # A file that does not end in a newline gets one before the section, so the
  # original bytes stay a prefix of the output.
  [ -n "$(tail -c 1 "$AGENTS_FILE")" ] && printf '\n'
  printf '\n%s\n\n%s\n' "$MERGE_HEADING" "$BODY"
  exit 0
fi

# ── Above the project ─────────────────────────────────────────────────────────

ABOVE=""
USER_FILE="${HOME%/}/.claude/CLAUDE.md"

is_user_file() {
  [ "$1" = "$USER_FILE" ] && return 0
  [ -e "$USER_FILE" ] && [ "$1" -ef "$USER_FILE" ]
}

CURRENT="$DIR"
while [ "$CURRENT" != "/" ] && [ -n "$CURRENT" ]; do
  CURRENT="$(dirname "$CURRENT")"
  PREFIX="${CURRENT%/}"
  for CANDIDATE in "$PREFIX/CLAUDE.md" "$PREFIX/.claude/CLAUDE.md" "$PREFIX/CLAUDE.local.md"; do
    [ -e "$CANDIDATE" ] || continue
    is_user_file "$CANDIDATE" && continue
    ABOVE="$(append "$ABOVE" "$CANDIDATE")"
  done
done

# ── The client version ────────────────────────────────────────────────────────

# True when version $1 is at least $2, compared as integers per component, so
# 2.1.29 < 2.1.281 < 2.1.1000.
version_at_least() {
  local IFS=. i
  # shellcheck disable=SC2206
  local a=($1) b=($2)
  for i in 0 1 2; do
    if [ "$((10#${a[$i]:-0}))" -gt "$((10#${b[$i]:-0}))" ]; then return 0; fi
    if [ "$((10#${a[$i]:-0}))" -lt "$((10#${b[$i]:-0}))" ]; then return 1; fi
  done
  return 0
}

CLAUDE_VERSION=""
VERSION_OK=""
if command -v claude >/dev/null 2>&1; then
  CLAUDE_VERSION="$(claude --version 2>/dev/null | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -n 1)"
  [ -n "$CLAUDE_VERSION" ] || warn "claude --version printed no version"
else
  warn "claude is not on PATH: the client version is not verified"
fi
if [ -n "$CLAUDE_VERSION" ]; then
  if version_at_least "$CLAUDE_VERSION" "$MIN_CLAUDE_VERSION"; then
    VERSION_OK=true
  else
    VERSION_OK=false
  fi
fi

# ── Output ────────────────────────────────────────────────────────────────────

json_set SHIMS "$SHIMS"
json_set CUSTOM "$CUSTOM"
json_set UNIMPORTED "$UNIMPORTED"
json_set LOCAL "$LOCAL"
json_set ABOVE "$ABOVE"
json_set CLAUDE_VERSION "$CLAUDE_VERSION"
json_set MIN_CLAUDE_VERSION "$MIN_CLAUDE_VERSION"
json_set VERSION_OK "$VERSION_OK"

if [ "$AS_JSON" = true ]; then
  json_emit
else
  json_emit_text
fi
